var n=`0434-kj-ttkaker`;var o=`world-0434`;var i=`NO`;var a=`northern-europe`;var r=4;var s=43;var l={en:`Kjøttkaker`,ua:`М'ясні котлетки по-норвезьки`};var u={en:`A traditional dish from Norway, centered on ground beef, yellow onion, chicken egg, potato starch. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Норвегія. Основні складники: яловичий фарш, жовта цибуля, куряче яйце, картопляний крохмаль. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`ground-beef`,550,`g`],[`yellow-onion`,120,`g`],[`chicken-egg`,1,`pcs`],[`potato-starch`,35,`g`],[`whole-cow-milk`,150,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`unsalted-butter`,65,`g`]]},{en:`Melt the fat, stir in flour and cook gently for about 8 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 8 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:8,i:[[`unsalted-butter`,35,`g`],[`all-purpose-flour`,35,`g`],[`beef-stock`,350,`ml`]]},{en:`Simmer lingonberries with sugar into a small sweet-tart sauce and serve on the side.`,ua:`Коротко проваріть брусницю з цукром до кисло-солодкого соусу й подавайте окремо.`,t:[`sauteing`,`reducing-sauce`],m:8,i:[[`lingonberry`,100,`g`],[`white-granulated-sugar`,30,`g`]]}];var d={slug:n,id:o,country:`NO`,region:a,servings:4,minutes:43,title:l,text:u,steps:g};export{i as country,d as default,o as id,s as minutes,a as region,r as servings,n as slug,g as steps,u as text,l as title};